import{_ as e,o as l,c as a,a4 as i}from"./chunks/framework.2-Vke5-n.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"メール設計ガイドライン","tagline":"Mail Design Guidelines","actions":[{"theme":"brand","text":"メール設計ガイドライン","link":"./mail_guidelines.md"},{"theme":"alt","text":"SMS設計ガイドライン","link":"./sms_guidelines.md"}]}},"headers":[],"relativePath":"documents/forMail/index.md","filePath":"documents/forMail/index.md"}'),r={name:"documents/forMail/index.md"};function o(n,t,s,d,c,h){return l(),a("div",null,[...t[0]||(t[0]=[i('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>電子メールは、SMTP（Simple Mail Transfer Protocol）プロトコルが1980年代初頭に標準化されて以来、半世紀近くにわたり利用されている。多くのサービスで 「認証」 「販売促進」 「トランザクションの証明」 などにメールが用いられており、ユーザー体験にも直結する。</p><p>しかし、その長い歴史ゆえに、古典的な技術知識だけでは対応しきれない到達性の低下や遅延などの課題を引き起こしやすい。これはクラウドプロバイダーが提供するEメール送信サービスを用いても起こりえるため、モダンな環境下でも無視はできない。</p><p>そのため、SMTPプロトコルの理解に加えて、クラウドベースのメール配信サービスの特性を理解し、要件に応じて設計する能力が求められる。特に大規模なシステムでは信頼性・費用・保守運用制などの非機能要件も求められる。本ガイドラインは、メール送信で考慮すべき設計事項と推奨案をまとめる。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署 / プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="適用範囲" tabindex="-1">適用範囲 <a class="header-anchor" href="#適用範囲" aria-label="Permalink to &quot;適用範囲&quot;">​</a></h2><ul><li>コンシューマー（一般ユーザー）向けのメール送信を対象とする <ul><li>ただし、同一用途で使われるLINEについては本ドキュメントでは触れない</li></ul></li><li><a href="https://laws.e-gov.go.jp/law/359AC0000000086" target="_blank" rel="noreferrer">電気通信事業法</a>でいう「電気通信事業」に<strong>該当しない</strong>通信である、取引関係に伴う事務連絡や企業からユーザーへの広告宣伝を目的する</li><li>システムからの自動送信メールを対象とする。手動送信でのメルマガ送信や営業メールは対象外とする</li><li>企業のシステム管理者向けのメール送信（例えば、障害通知など）については、参考にできる部分も多いと思われるが、強く意識していない</li><li>ServiceNowやZendeskといったメールを含む問い合わせ管理のSaaSサービスの運用設計やサービス選定なども対象外とする</li><li>主要なクラウドサービス（AWS SES, Microsoft Azure Communication Services, Google Cloud, SendGridなど）を用いるとし、スクラッチやOSSなどでのSMTPサーバーの構築や運用については、触れないとする</li></ul><h2 id="用語" tabindex="-1">用語 <a class="header-anchor" href="#用語" aria-label="Permalink to &quot;用語&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">用語</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;">トランザクションメール</td><td style="text-align:left;">ログイン通知や注文完了通知といったユーザーのアクションや、サービスの重要な変更をきっかけに送信される企業にとって重要な通知。ユーザーとの信頼関係を構築し、アカウントのセキュリティを保つ上で重要である</td></tr><tr><td style="text-align:left;">マーケティングメール</td><td style="text-align:left;">メールマガジンなどの広告・宣伝に用いるメール。販売促進や顧客との関係構築に重要なツールであるが、一歩間違えると迷惑メールとして認識され、逆にブランドイメージを下げてしまう</td></tr><tr><td style="text-align:left;">キャリアメール</td><td style="text-align:left;">国内携帯通信キャリア（docomo, au, Softbank, 楽天）を指す</td></tr><tr><td style="text-align:left;">ESP</td><td style="text-align:left;">メール配信サービス（Email Service Provider）のこと。SendGridやAmazon SESなどが存在する</td></tr></tbody></table><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、藤井亮佑、前原応光、宮崎将太、澁川喜規</li><li><strong>レビュアー</strong>: 募集中</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2025.10.03 <a href="https://future-architect.github.io/articles/20251003a/" target="_blank" rel="noreferrer">メール設計ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./mail_guidelines.html">メール設計ガイドライン</a></p></div>',15)])])}const m=e(r,[["render",o]]);export{f as __pageData,m as default};
